Method.Source:
    /// <summary>
    /// Updating all records with default dimension from header journal
    /// </summary>
    public void clicked()
    {
        next clicked();

        FormDataSource      formDatasource          = this.formRun().dataSource(tableStr(LedgerJournalTrans));
        LedgerJournalTrans  metLedgerJournalTrans   = formDatasource.cursor();
        LedgerJournalTable  metLedgerJournalTable   = LedgerJournalTable::find(metLedgerJournalTrans.JournalNum);
        LedgerJournalName   metLedgerJournalName    = LedgerJournalName::find(metLedgerJournalTable.journalname);
        LedgerJournalTrans  metUpdateLedgerJournalTrans;

        if (metLedgerJournalName.METFreezeDefaultDimensions == NoYes::Yes)
        {
            update_recordset metUpdateLedgerJournalTrans
                setting
                    DefaultDimension = metLedgerJournalTable.DefaultDimension
                where 
                    metUpdateLedgerJournalTrans.JournalNum == metLedgerJournalTable.JournalNum;
        }

        formDatasource.research();

    }
